final class DatevExportService {
 public function __construct(private IDBConnection $db,private IConfig $config,private IUserSession $session,private IURLGenerator $url){}
 public function export(?string $from=null,?string $to=null):DataDownloadResponse|RedirectResponse{
  $settings=$this->settings();$from=$from?:date('Y-m-01');$to=$to?:date('Y-m-t');
  if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to)return $this->back('Ungültiger DATEV-Zeitraum.');
  if($settings['consultant_no']===''||$settings['client_no']==='')return $this->back('DATEV-Export nicht möglich: Bitte zuerst Beraternummer und Mandantennummer in den DATEV-Einstellungen hinterlegen.');
  if(!preg_match('/^\d{1,7}$/',(string)$settings['consultant_no'])||!preg_match('/^\d{1,5}$/',(string)$settings['client_no']))return $this->back('DATEV-Export nicht möglich: Beraternummer oder Mandantennummer haben kein gültiges Zahlenformat.');
  $accountLength=(int)$settings['account_length'];if($accountLength<4||$accountLength>8)return $this->back('DATEV-Export nicht möglich: Bitte die Sachkontenlänge in den DATEV-Einstellungen prüfen.');foreach(['revenue19','revenue7','revenue0','expense_material','expense_external_service','expense_machine','expense_travel','expense_other'] as $k){if(!preg_match('/^\d{'.$accountLength.'}$/',(string)$settings[$k]))return $this->back('DATEV-Export nicht möglich: Die Erlöskonten müssen zur eingestellten Sachkontenlänge passen.');}
  $q=$this->db->getQueryBuilder();$q->select('i.*','c.name AS customer_name','c.datev_debtor_account','o.order_no')->from('re_erp_invoices','i')->leftJoin('i','re_erp_customers','c',$q->expr()->eq('c.id','i.customer_id'))->leftJoin('i','re_erp_orders','o',$q->expr()->eq('o.id','i.order_id'))->where($q->expr()->gte('i.invoice_date',$q->createNamedParameter($from)))->andWhere($q->expr()->lte('i.invoice_date',$q->createNamedParameter($to)))->andWhere($q->expr()->neq('i.status',$q->createNamedParameter('draft')))->andWhere($q->expr()->isNotNull('i.finalized_at'))->orderBy('i.invoice_date','ASC')->addOrderBy('i.id','ASC');$result=$q->executeQuery();$rows=[];while($row=$result->fetch())$rows[]=$row;$result->closeCursor();
  $iq=$this->db->getQueryBuilder();$iq->select('d.*','s.name AS supplier_name','s.datev_creditor_account','p.project_no')->from('re_erp_documents','d')->leftJoin('d','re_erp_suppliers','s',$iq->expr()->eq('s.id','d.supplier_id'))->leftJoin('d','re_erp_projects','p',$iq->expr()->eq('p.id','d.project_id'))->where($iq->expr()->eq('d.document_type',$iq->createNamedParameter('incoming_invoice')))->andWhere($iq->expr()->eq('d.status',$iq->createNamedParameter('assigned')))->andWhere($iq->expr()->gte('d.document_date',$iq->createNamedParameter($from)))->andWhere($iq->expr()->lte('d.document_date',$iq->createNamedParameter($to)))->orderBy('d.document_date','ASC')->addOrderBy('d.id','ASC');$incoming=$iq->executeQuery()->fetchAll();
  $fh=fopen('php://temp','w+');if($fh===false)throw new \RuntimeException('DATEV-Export konnte nicht erstellt werden.');$d=';';$fyYear=(int)substr($from,0,4);$md=(string)$settings['fiscal_year_start'];$fyStart=sprintf('%04d%s',$fyYear,str_replace('-','',$md));if($from<substr($from,0,4).'-'.$md)$fyStart=sprintf('%04d%s',$fyYear-1,str_replace('-','',$md));$created=date('YmdHis000');$header=['EXTF','700','21','Buchungsstapel','12',$created,'','RE','Betrio','',(string)$settings['consultant_no'],(string)$settings['client_no'],$fyStart,(string)$settings['account_length'],date('Ymd',strtotime($from)),date('Ymd',strtotime($to)),'Betrio Ein- und Ausgangsrechnungen','','','','','','','','','','','','','','EUR'];fputcsv($fh,$header,$d,'"','\\');
  $cols=['Umsatz (ohne Soll/Haben-Kz)','Soll/Haben-Kennzeichen','WKZ Umsatz','Kurs','Basis-Umsatz','WKZ Basis-Umsatz','Konto','Gegenkonto (ohne BU-Schlüssel)','BU-Schlüssel','Belegdatum','Belegfeld 1','Belegfeld 2','Skonto','Buchungstext','Postensperre','Diverse Adressnummer','Geschäftspartnerbank','Sachverhalt','Zinssperre','Beleglink','Beleginfo - Art 1','Beleginfo - Inhalt 1','Beleginfo - Art 2','Beleginfo - Inhalt 2','Beleginfo - Art 3','Beleginfo - Inhalt 3','Beleginfo - Art 4','Beleginfo - Inhalt 4','Beleginfo - Art 5','Beleginfo - Inhalt 5','Beleginfo - Art 6','Beleginfo - Inhalt 6','Beleginfo - Art 7','Beleginfo - Inhalt 7','Beleginfo - Art 8','Beleginfo - Inhalt 8','KOST1 - Kostenstelle','KOST2 - Kostenstelle','KOST-Menge','EU-Land u. UStID','EU-Steuersatz','Abw. Versteuerungsart','Sachverhalt L+L','Funktionsergänzung L+L','BU 49 Hauptfunktionstyp','BU 49 Hauptfunktionsnummer','BU 49 Funktionsergänzung','Zusatzinformation - Art 1','Zusatzinformation - Inhalt 1','Stück','Gewicht','Zahlweise','Forderungsart','Veranlagungsjahr','Zugeordnete Fälligkeit','Skontotyp','Auftragsnummer','Buchungstyp','USt-Schlüssel (Anzahlungen)','EU-Land (Anzahlungen)','Sachverhalt L+L (Anzahlungen)','EU-Steuersatz (Anzahlungen)','Erlöskonto (Anzahlungen)','Herkunft-Kz','Buchungs GUID','KOST-Datum','SEPA-Mandatsreferenz','Skontosperre','Gesellschaftername','Beteiligtennummer','Identifikationsnummer','Zeichnernummer','Postensperre bis','Bezeichnung SoBil-Sachverhalt','Kennzeichen SoBil-Buchung','Festschreibung','Leistungsdatum','Datum Zuord. Steuerperiode'];fputcsv($fh,$cols,$d,'"','\\');
  foreach($rows as $r){$gross=abs((float)$r['gross_amount']);if($gross<=0)continue;$isCredit=(($r['invoice_type']??'')==='credit');$debtor=trim((string)($r['datev_debtor_account']??''));if($debtor==='')$debtor=(string)((int)$settings['debtor_base']+(int)$r['customer_id']);$vat=(float)($r['vat_rate']??0);$revenue=(string)($vat>=18.5?$settings['revenue19']:($vat>=6.5?$settings['revenue7']:$settings['revenue0']));$text=trim((string)($r['customer_name']??''))?:'Ausgangsrechnung';$row=array_fill(0,count($cols),'');$row[0]=number_format($gross,2,',','');$row[1]=$isCredit?'H':'S';$row[2]='EUR';$row[6]=$debtor;$row[7]=$revenue;$row[9]=date('dm',strtotime((string)$r['invoice_date']));$row[10]=(string)($r['invoice_no']??'');$row[13]=mb_substr('Betrio '.$text,0,60);$row[56]=(string)($r['order_no']??'');$docRef=$this->documentReference($r);if($docRef['file']!==''){$row[20]='Belegdatei';$row[21]=$docRef['file'];}$row[22]='Beleg-GUID';$row[23]=$docRef['guid'];$row[64]=$docRef['guid'];$row[75]='1';if(!empty($r['service_date'])){$row[76]=date('dmY',strtotime((string)$r['service_date']));$row[77]=$row[76];}fputcsv($fh,$row,$d,'"','\\');}
  foreach($incoming as $r){$gross=abs((float)($r['gross_amount']??0));if($gross<=0||empty($r['supplier_id'])||empty($r['document_no']))continue;$creditor=trim((string)($r['datev_creditor_account']??''));if($creditor==='')$creditor=(string)((int)$settings['creditor_base']+(int)$r['supplier_id']);$category=(string)($r['cost_category']??'other');$expense=trim((string)($r['datev_expense_account']??''));if($expense==='')$expense=(string)($settings['expense_'.$category]??$settings['expense_other']);$vat=(float)($r['datev_vat_rate']??0);if(!in_array(round($vat,2),[0.0,7.0,19.0],true))continue;$text=trim((string)($r['supplier_name']??''))?:'Eingangsrechnung';$row=array_fill(0,count($cols),'');$row[0]=number_format($gross,2,',','');$row[1]='S';$row[2]=strtoupper((string)($r['currency']??'EUR'))?:'EUR';$row[6]=$expense;$row[7]=$creditor;$row[8]=$vat>=18.5?'9':($vat>=6.5?'8':'');$row[9]=date('dm',strtotime((string)$r['document_date']));$row[10]=(string)$r['document_no'];$row[13]=mb_substr('Betrio '.$text,0,60);$row[36]=(string)($r['project_no']??'');$row[20]='Belegdatei';$row[21]=(string)($r['file_path']??'');$guid=$this->documentGuid((int)$r['id'],(string)$r['document_no']);$row[22]='Beleg-GUID';$row[23]=$guid;$row[64]=$guid;$row[75]='1';fputcsv($fh,$row,$d,'"','\\');}
  rewind($fh);$csv=stream_get_contents($fh);fclose($fh);if($csv===false)$csv='';$csv=str_replace(["\r\n","\r"],"\n",$csv);$csv=str_replace("\n","\r\n",$csv);$encoded=@iconv('UTF-8','Windows-1252//TRANSLIT',$csv);if($encoded!==false)$csv=$encoded;foreach($rows as $r){if(!empty($r['id']))$this->audit((int)$r['id'],['from'=>$from,'to'=>$to,'format'=>'EXTF','version'=>'700/12']);}return new DataDownloadResponse($csv,'EXTF_Buchungsstapel_Betrio_'.$from.'_'.$to.'.csv','text/csv; charset=Windows-1252');
 }
 private function back(string $error):RedirectResponse{return new RedirectResponse($this->url->linkToRoute('reinhardterp.business.invoices').'?datev_error='.rawurlencode($error));}
 private function settings():array{$skr=$this->config->getAppValue('reinhardterp','datev_skr','03');if(!in_array($skr,['03','04'],true))$skr='03';return ['skr'=>$skr,'debtor_base'=>(int)$this->config->getAppValue('reinhardterp','datev_debtor_base','10000'),'creditor_base'=>(int)$this->config->getAppValue('reinhardterp','datev_creditor_base','70000'),'expense_material'=>$this->config->getAppValue('reinhardterp','datev_expense_material',$skr==='04'?'5200':'3400'),'expense_external_service'=>$this->config->getAppValue('reinhardterp','datev_expense_external_service',$skr==='04'?'5900':'3100'),'expense_machine'=>$this->config->getAppValue('reinhardterp','datev_expense_machine',$skr==='04'?'6495':'4900'),'expense_travel'=>$this->config->getAppValue('reinhardterp','datev_expense_travel',$skr==='04'?'6670':'4660'),'expense_other'=>$this->config->getAppValue('reinhardterp','datev_expense_other',$skr==='04'?'6300':'4980'),'revenue19'=>$this->config->getAppValue('reinhardterp','datev_revenue19',$skr==='04'?'4400':'8400'),'revenue7'=>$this->config->getAppValue('reinhardterp','datev_revenue7',$skr==='04'?'4300':'8300'),'revenue0'=>$this->config->getAppValue('reinhardterp','datev_revenue0',$skr==='04'?'4120':'8120'),'consultant_no'=>$this->config->getAppValue('reinhardterp','datev_consultant_no',''),'client_no'=>$this->config->getAppValue('reinhardterp','datev_client_no',''),'account_length'=>(int)$this->config->getAppValue('reinhardterp','datev_account_length','4'),'fiscal_year_start'=>$this->config->getAppValue('reinhardterp','datev_fiscal_year_start','01-01')];}
 private function documentReference(array $invoice):array{$id=(int)($invoice['id']??0);$invoiceNo=trim((string)($invoice['invoice_no']??''));$invoiceDate=(string)($invoice['invoice_date']??'');$file='';if($id>0){$q=$this->db->getQueryBuilder();$q->select('details')->from('re_erp_invoice_audit')->where($q->expr()->eq('invoice_id',$q->createNamedParameter($id)))->andWhere($q->expr()->eq('event_type',$q->createNamedParameter('finalized')))->orderBy('id','DESC')->setMaxResults(1);$details=$q->executeQuery()->fetchOne();if(is_string($details)&&$details!==''){$decoded=json_decode($details,true);if(is_array($decoded))$file=trim((string)($decoded['archive']??''));}}if($file!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$invoiceDate)){$ts=strtotime($invoiceDate);if($ts!==false)$file='ERP/30_Finanzen/Ausgangsrechnungen/'.date('Y',$ts).'/'.date('m',$ts).'/'.$file;}$seed='reinhardterp|invoice|'.$id.'|'.$invoiceNo;$hex=hash('sha256',$seed);$guid=substr($hex,0,8).'-'.substr($hex,8,4).'-5'.substr($hex,13,3).'-'.dechex((hexdec($hex[16])&3)|8).substr($hex,17,3).'-'.substr($hex,20,12);return ['file'=>$file,'guid'=>$guid];}
 private function documentGuid(int $id,string $documentNo):string{$hex=hash('sha256','reinhardterp|incoming|'.$id.'|'.$documentNo);return substr($hex,0,8).'-'.substr($hex,8,4).'-5'.substr($hex,13,3).'-'.dechex((hexdec($hex[16])&3)|8).substr($hex,17,3).'-'.substr($hex,20,12);}
 private function audit(int $invoiceId,array $details):void{$q=$this->db->getQueryBuilder();$q->insert('re_erp_invoice_audit')->values(['invoice_id'=>$q->createNamedParameter($invoiceId),'event_type'=>$q->createNamedParameter('datev_exported'),'user_id'=>$q->createNamedParameter($this->session->getUser()?->getUID()),'event_at'=>$q->createNamedParameter(date('Y-m-d H:i:s')),'details'=>$q->createNamedParameter(json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)),'snapshot_hash'=>$q->createNamedParameter(null)]);$q->executeStatement();}
}
